  blend+=gridX+gridY;
  const wX=20,wY=15,wW=140,wH=80;
  const inWin=x>=wX&&x<wX+wW&&y>=wY&&y<wY+wH;
  const winBorder=(x===wX||x===wX+wW-1||y===wY||y===wY+wH-1)?1:0;
