  let g=(neon[i][1]+(neon[i+1][1]-neon[i][1])*f)*lum*edge;
  let b=(neon[i][2]+(neon[i+1][2]-neon[i][2])*f)*lum*edge;
  if(ui>0){r+=ui*200*uiGlow;g+=ui*220*uiGlow;b+=ui*255*uiGlow;}
  return[Math.min(255,r)|0,Math.min(255,g)|0,Math.min(255,b)|0];
}
